<template><div class="app-state"><div class="state-icon" :class="type"><el-icon><component :is="type==='error'?'WarningFilled':'Box'"/></el-icon></div><b>{{title||defaultTitle}}</b><p>{{description||defaultDescription}}</p><el-button v-if="action" type="primary" :loading="loading" @click="$emit('action')">{{action}}</el-button></div></template>
<script setup>import{computed}from'vue';const props=defineProps({type:{type:String,default:'empty'},title:String,description:String,action:String,loading:Boolean});defineEmits(['action']);const defaultTitle=computed(()=>props.type==='error'?'内容加载失败':'暂时没有内容'),defaultDescription=computed(()=>props.type==='error'?'请检查网络连接后重试':'新的内容出现后会展示在这里')</script>
<style scoped>.app-state{min-height:230px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.state-icon{width:58px;height:58px;display:grid;place-items:center;border-radius:18px;background:rgba(var(--accent-rgb),.09);color:var(--accent);font-size:27px;animation:state-float 4s ease-in-out infinite}.state-icon.error{color:#d84b4b;background:#fff0f0}.app-state b{margin-top:14px}.app-state p{margin:7px 0 15px;color:#8995a8;font-size:13px}@keyframes state-float{50%{transform:translateY(-3px)}}@media(prefers-reduced-motion:reduce){.state-icon{animation:none}}</style>
